{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-fs-electric-studio",
  "title": "Write a B2B SaaS Sales Proposal like a Tier-1 Enterprise AE",
  "title_i18n": {
    "en": "Write a B2B SaaS Sales Proposal like a Tier-1 Enterprise AE",
    "zh-CN": "像一线企业客户 AE 一样写 B2B SaaS 销售提案",
    "zh-TW": "像一线企业客户 AE 一样写 B2B SaaS 销售提案"
  },
  "version": "1.0.0",
  "publishedAt": "2026-06-16T09:32:15Z",
  "description": "Open Design as an enterprise design platform: a buyer-forwardable proposal for a design-org's economic buyer — pain, value, ROI, rollout. Built as a decision-grade B2B sales deck for economic buyer, design VP, procurement.",
  "description_i18n": {
    "en": "Open Design as an enterprise design platform: a buyer-forwardable proposal for a design-org's economic buyer — pain, value, ROI, rollout. Built as a decision-grade B2B sales deck for economic buyer, design VP, procurement.",
    "zh-CN": "像一线企业客户 AE 一样写 B2B SaaS 销售提案——一份可商业交付的B2B 销售 Deck，围绕真实主题、证据链与决策目标组织。",
    "zh-TW": "像一线企业客户 AE 一样写 B2B SaaS 销售提案——一份可商业交付的B2B 销售 Deck，围绕真实主题、证据链与决策目标组织。"
  },
  "license": "MIT",
  "author": {
    "name": "zarazhangrui",
    "url": "https://github.com/zarazhangrui"
  },
  "homepage": "https://github.com/zarazhangrui/frontend-slides",
  "plugin": {
    "repo": "https://github.com/zarazhangrui/frontend-slides"
  },
  "tags": [
    "community",
    "deck",
    "slides",
    "presentation",
    "split-panel",
    "cobalt",
    "bold",
    "manrope",
    "web",
    "ppt",
    "sales",
    "renewal",
    "customer",
    "fs-electric-studio",
    "b2b-sales",
    "b2b-saas-sales-proposal",
    "decision-deck",
    "commercial-slide-agent"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "deck",
    "scenario": "sales",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html",
      "motion": "deck"
    },
    "useCase": {
      "query": {
        "en": "Create \"Write a B2B SaaS Sales Proposal like a Tier-1 Enterprise AE\" as a decision-grade B2B sales deck in this template's own visual system. Subject: Open Design as an enterprise design platform: a buyer-forwardable proposal for a design-org's economic buyer — pain, value, ROI, rollout. Audience: economic buyer, design VP, procurement. First ask only for missing essentials: audience, decision target, source-of-truth materials, deadline, and must-keep numbers. Then produce the slide plan, written slides, visual direction, speaker-ready structure, and a critic pass against this rubric: can the champion forward this internally without rewriting it.",
        "zh-CN": "像一线企业客户 AE 一样写 B2B SaaS 销售提案。像一线企业客户 AE 一样写 B2B SaaS 销售提案——一份可商业交付的B2B 销售 Deck，围绕真实主题、证据链与决策目标组织。 主题：Open Design as an enterprise design platform: a buyer-forwardable proposal for a design-org's economic buyer — pain, value, ROI, rollout. 先确认受众、决策目标、素材来源、截止时间和必须保留的数据，再输出叙事主线、页面规划、逐页文案、视觉方向和按评审标准自检的版本。"
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Write a B2B SaaS Sales Proposal like a Tier-1 Enterprise AE",
          "title_i18n": {
            "en": "Write a B2B SaaS Sales Proposal like a Tier-1 Enterprise AE",
            "zh-CN": "像一线企业客户 AE 一样写 B2B SaaS 销售提案",
            "zh-TW": "像一线企业客户 AE 一样写 B2B SaaS 销售提案"
          }
        }
      ]
    },
    "inputs": [
      {
        "name": "deckType",
        "label": "Deck type",
        "type": "select",
        "required": true,
        "options": [
          "studio / agency capabilities deck",
          "pitch deck",
          "product overview",
          "conference talk",
          "internal presentation"
        ],
        "default": "studio / agency capabilities deck"
      },
      {
        "name": "topic",
        "label": "Topic",
        "type": "string",
        "required": true,
        "placeholder": "Voltaic Studio capabilities 2026",
        "default": "the user's brief"
      },
      {
        "name": "audience",
        "label": "Audience",
        "type": "string",
        "required": true,
        "placeholder": "Prospective clients evaluating design partners",
        "default": "a general professional audience"
      },
      {
        "name": "slideCount",
        "label": "Length",
        "type": "select",
        "required": true,
        "options": [
          "short 5-10 slides",
          "medium 10-20 slides",
          "long 20+ slides"
        ],
        "default": "short 5-10 slides"
      },
      {
        "name": "density",
        "label": "Density",
        "type": "select",
        "required": true,
        "options": [
          "low density / speaker-led",
          "high density / reading-first"
        ],
        "default": "low density / speaker-led"
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "discovery",
          "atoms": [
            "discovery-question-form"
          ]
        },
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ],
    "category": "b2b-sales"
  }
}
